protected override async Task OnInitializedAsync()
{
    var width = await JS.InvokeAsync<int>("getWidth"); // BLOCKER: DOM not ready
}

guardrail.good:
protected override async Task OnAfterRenderAsync(bool firstRender)
{
    if (firstRender)
    {
        var width = await JS.InvokeAsync<int>("getWidth");
    }
}

guardrail.bad:
[Parameter]
public string Title { get; set; } = "";

private void Update() { Title = "new"; } // BLOCKER: mutating a Parameter

guardrail.good:
[Parameter]
public string Title { get; set; } = "";

private string localTitle = "";

protected override void OnParametersSet() { localTitle = Title; }
private void Update() { localTitle = "new"; }

guardrail.bad:
@inject AppState State

protected override void OnInitialized()
{
    State.OnChange += StateHasChanged; // BLOCKER: never unsubscribed — memory leak
}

guardrail.good:
@inject AppState State
@implements IDisposable

protected override void OnInitialized()
{
    State.OnChange += StateHasChanged;
}

public void Dispose()
{
    State.OnChange -= StateHasChanged;
}

